CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255),email_verified_at DATETIME NULL,email_verification_token VARCHAR(128),ai_credits INT NOT NULL DEFAULT 100,remember_token VARCHAR(128),created_at DATETIME,updated_at DATETIME NULL,deleted_at DATETIME NULL,INDEX(email),INDEX(deleted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE user_profiles (user_id BIGINT UNSIGNED PRIMARY KEY,phone VARCHAR(60),location VARCHAR(190),website VARCHAR(255),linkedin VARCHAR(255),github VARCHAR(255),portfolio VARCHAR(255),photo_path VARCHAR(255),privacy_json JSON,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oauth_accounts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,provider VARCHAR(40) NOT NULL,provider_user_id VARCHAR(190) NOT NULL,email VARCHAR(190),created_at DATETIME,UNIQUE(provider,provider_user_id),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resumes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(190) NOT NULL,template_key VARCHAR(80) NOT NULL DEFAULT 'modern',content_json JSON NOT NULL,section_order JSON,public_token VARCHAR(64) NOT NULL UNIQUE,public_enabled TINYINT(1) NOT NULL DEFAULT 0,ats_score INT NULL,completion_percent INT NOT NULL DEFAULT 0,archived_at DATETIME NULL,created_at DATETIME,updated_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX(user_id),INDEX(public_token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_versions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,resume_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,snapshot_json JSON NOT NULL,source VARCHAR(40) NOT NULL,created_at DATETIME,FOREIGN KEY(resume_id) REFERENCES resumes(id) ON DELETE CASCADE,INDEX(resume_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE resume_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_key VARCHAR(80) UNIQUE,name VARCHAR(120),settings_json JSON,is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_providers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,type ENUM('openai','anthropic','gemini','custom') NOT NULL DEFAULT 'custom',base_url VARCHAR(255),api_key TEXT NOT NULL,model VARCHAR(120) NOT NULL,temperature DECIMAL(3,2) DEFAULT 0.40,max_tokens INT DEFAULT 800,headers_json JSON,is_active TINYINT(1) DEFAULT 0,priority INT DEFAULT 100,estimated_input_cost DECIMAL(12,6) DEFAULT 0,estimated_output_cost DECIMAL(12,6) DEFAULT 0,created_at DATETIME,updated_at DATETIME,INDEX(is_active,priority)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_prompts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,prompt_key VARCHAR(100) UNIQUE,name VARCHAR(160),system_prompt TEXT,user_prompt TEXT,temperature DECIMAL(3,2) DEFAULT 0.40,max_tokens INT DEFAULT 800,is_active TINYINT(1) DEFAULT 1,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,provider_id BIGINT UNSIGNED NULL,model VARCHAR(120),request_type VARCHAR(100),status VARCHAR(40),tokens_input INT DEFAULT 0,tokens_output INT DEFAULT 0,error TEXT,response_time_ms INT,created_at DATETIME,INDEX(provider_id),INDEX(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ai_credit_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,request_id VARCHAR(80) NOT NULL UNIQUE,action VARCHAR(100),credits INT NOT NULL,provider_id BIGINT UNSIGNED NULL,model VARCHAR(120),created_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE plans (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),slug VARCHAR(80) UNIQUE,price DECIMAL(10,2) DEFAULT 0,currency VARCHAR(8) DEFAULT 'USD',features_json JSON,limits_json JSON,is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE subscriptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,plan_id BIGINT UNSIGNED,status VARCHAR(40),starts_at DATETIME,ends_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(plan_id) REFERENCES plans(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,provider VARCHAR(40),provider_payment_id VARCHAR(190),amount DECIMAL(10,2),currency VARCHAR(8),status VARCHAR(40),verified_at DATETIME,created_at DATETIME,INDEX(provider,provider_payment_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE admin_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),email VARCHAR(190) UNIQUE,password_hash VARCHAR(255),role ENUM('Super Admin','Admin','Support','Content Manager') DEFAULT 'Admin',created_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE system_settings (setting_key VARCHAR(120) PRIMARY KEY,setting_value TEXT,is_secret TINYINT(1) DEFAULT 0,updated_at DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_templates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_key VARCHAR(100) UNIQUE,subject VARCHAR(190),body_html MEDIUMTEXT,is_active TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED,title VARCHAR(190),body TEXT,read_at DATETIME NULL,created_at DATETIME,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE password_resets (email VARCHAR(190),token VARCHAR(128),created_at DATETIME,INDEX(email),INDEX(token)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE email_verifications (user_id BIGINT UNSIGNED,token VARCHAR(128),created_at DATETIME,INDEX(token),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO plans(name,slug,price,currency,features_json,limits_json) VALUES ('Free','free',0,'USD',JSON_OBJECT('templates','Basic','ats','Basic'),JSON_OBJECT('cvs',1,'ai_credits',100)),('Pro','pro',0,'USD',JSON_OBJECT('templates','All','ats','Advanced','cover_letters',true),JSON_OBJECT('cvs',25,'ai_credits',2000)),('Business','business',0,'USD',JSON_OBJECT('priority_ai',true,'advanced_analytics',true),JSON_OBJECT('cvs',100,'ai_credits',10000));
INSERT INTO resume_templates(template_key,name,settings_json) VALUES ('modern','Modern',JSON_OBJECT('font','Inter','accent','#3157ff')),('classic','Classic',JSON_OBJECT('font','Georgia','accent','#1f2937')),('executive','Executive',JSON_OBJECT('font','Inter','accent','#7c2d12')),('minimal','Minimal',JSON_OBJECT('font','Arial','accent','#111827')),('professional','Professional',JSON_OBJECT('font','Inter','accent','#0f766e')),('technical','Technical',JSON_OBJECT('font','IBM Plex Mono','accent','#2563eb')),('creative','Creative',JSON_OBJECT('font','Inter','accent','#9333ea')),('ats','ATS Focused',JSON_OBJECT('font','Arial','accent','#111827'));
INSERT INTO ai_prompts(prompt_key,name,system_prompt,user_prompt) VALUES ('summary_generator','Resume Summary Generator','You improve resume content. Never invent employment, education, certifications, companies, dates, or achievements. Return JSON with content and review_notes.','Create a concise {{job_title}} professional summary for {{name}} using only these facts: skills={{skills}}, experience={{experience}}, education={{education}}.'),('experience_writer','AI Experience Writer','You convert truthful responsibilities into achievement-focused bullet points. If metrics are missing, mark suggestions for review. Return JSON.','Improve these experience notes without inventing facts: {{experience}}'),('skills_generator','AI Skills Generator','Suggest relevant skills based only on provided facts and job description. Return JSON.','Job title: {{job_title}} Skills: {{skills}} Job: {{job_description}}');
